168→            padding: 8px 12px;
169→            background-color: #ffffff66;
170→            border: 1px solid #dee2e6;
171→            border-radius: 4px;
172→            text-decoration: none;
173→            color: #495057;
174→            transition: background-color 0.2s;
175→        }
176→
177→        .session-link:hover {
178→            background-color: #ffffff99;
