193→            background-color: #e8f4fd66;
194→            border-radius: 8px;
195→            padding: 16px;
196→            margin: 30px 0 20px 0;
197→            box-shadow: -7px -7px 10px #eeeeee44, 7px 7px 10px #00000011;
198→            border-left: #ffffff66 1px solid;
199→            border-top: #ffffff66 1px solid;
200→            border-bottom: #00000017 1px solid;
201→            border-right: #00000017 1px solid;
202→        }
203→
204→        .session-header .header {
205→            margin-bottom: 8px;
206→            font-size: 1.2em;
207→        }
208→
