210→            position: fixed;
211→            bottom: 20px;
212→            right: 20px;
213→            background-color: #e8f4fd66;
214→            color: #ccc;
215→            border: none;
216→            border-radius: 50%;
217→            width: 50px;
218→            height: 50px;
219→            font-size: 1.5em;
220→            line-height: 1;
221→            text-decoration: none;
222→            display: flex;
223→            align-items: center;
224→            justify-content: center;
225→            box-shadow: 2px 2px 5px rgba(0, 0, 0, 0.2);
226→            transition: background-color 0.3s, transform 0.2s;
227→            z-index: 1000;
228→        }
229→
230→        .scroll-top:hover {
231→            background-color: #e8f4fdcc;
232→            transform: translateY(-2px);
233→        }
234→
235→        .scroll-top:visited {
236→            color: white;
237→        }
