239→        .session-summary {
240→            background-color: #ffffff66;
241→            border-left: #4caf5088 4px solid;
242→            padding: 12px;
243→            margin: 8px 0;
244→            border-radius: 0 4px 4px 0;
245→            font-style: italic;
246→            box-shadow: -7px -7px 10px #eeeeee44, 7px 7px 10px #00000011;
