269→        /* TodoWrite tool styling */
270→        .todo-write {
271→            background-color: #f0f8ff66;
272→            border-left: #4169e188 3px solid;
273→            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Helvetica Neue', Arial, sans-serif;
