275→
276→        .tool-header {
277→            font-weight: 600;
278→            margin-bottom: 12px;
279→            color: #2c3e50;
280→            font-size: 1.1em;
281→        }
282→
283→        .todo-list {
284→            background-color: #ffffff66;
285→            border-radius: 6px;
286→            padding: 8px;
287→            box-shadow: -7px -7px 10px #eeeeee44, 7px 7px 10px #00000011;
288→            border-left: #ffffff66 1px solid;
289→            border-top: #ffffff66 1px solid;
290→            border-bottom: #00000017 1px solid;
291→            border-right: #00000017 1px solid;
292→        }
293→
294→        .todo-item {
295→            display: flex;
296→            align-items: center;
297→            gap: 8px;
298→            padding: 8px 4px;
299→            border-bottom: 1px solid #f0f3f6;
300→            transition: background-color 0.2s ease;
301→        }
302→
303→        .todo-item:last-child {
304→            border-bottom: none;
305→        }
306→
307→        .todo-item:hover {
308→            background-color: #f8f9fa;
309→        }
310→
311→        .todo-item.completed {
312→            opacity: 0.7;
313→        }
314→
315→        .todo-item.completed .todo-content {
316→            text-decoration: line-through;
317→            color: #6c757d;
318→        }
319→
320→        .todo-item input[type="checkbox"] {
321→            margin: 0;
322→            cursor: default;
323→        }
324→
325→        .todo-status {
326→            font-size: 1.1em;
327→            line-height: 1;
328→        }
329→
330→        .todo-content {
331→            flex: 1;
332→            color: #333;
333→            font-weight: 500;
334→        }
335→
336→        .todo-id {
337→            font-size: 0.8em;
338→            color: #6c757d;
339→            font-weight: normal;
340→        }
341→
342→        /* Priority-based left border colors */
343→        .todo-item.high {
344→            border-left: 3px solid #dc3545;
345→        }
346→
347→        .todo-item.medium {
348→            border-left: 3px solid #ffc107;
349→        }
350→
351→        .todo-item.low {
352→            border-left: 3px solid #28a745;
353→        }
354→
355→        /* Status-based background tints */
356→        .todo-item.in_progress {
357→            background-color: #fff3cd;
358→        }
359→
360→        .todo-item.completed {
361→            background-color: #d4edda;
362→        }
363→    </style>
364→</head>
365→
366→<body>
367→    <h1 id="title">{{ title }}</h1>
368→
369→    {% if sessions and sessions|length > 1 %}
370→    <div class='navigation'>
371→        <h2>Sessions</h2>
372→        <span style='font-size: 0.75em;'>↓ Click a box below to scroll down to the corresponding
373→            session</span>
374→        <div class='session-nav'>
375→            {% for session in sessions %}
376→            <a href='#session-{{ session.id }}' class='session-link'>
377→                <div class='session-link-title'>
378→                    {% if session.summary %}
379→                    {{ session.summary }} •
380→                    {% endif %}
381→                    {{ session.id[:8] }}
382→                </div>
383→                <div class='session-link-meta'>
384→                    {{ session.timestamp_range }} • {{ session.message_count }} messages
385→                    {% if session.token_summary %}
386→                    <br>{{ session.token_summary }}
387→                    {% endif %}
388→                </div>
389→                {% if session.first_user_message %}
390→                <pre class='session-preview' style='font-size: 0.75em; line-height: 1.3; padding-bottom: 0;'>
391→                    {{- session.first_user_message[:500]|e -}}{% if session.first_user_message|length > 500 %}...{% endif %}
392→                </pre>
393→                {% endif %}
394→            </a>
395→            {% endfor %}
396→        </div>
397→    </div>
398→    {% endif %}
399→
400→    {% for message in messages %}
401→    {% if message.is_session_header %}
402→    <div class="session-divider"></div>
403→    <div id='session-{{ message.session_id }}' class='message session-header'>
404→        <div class='header'>Session: {{ message.content_html }}</div>
405→        {% if message.session_subtitle %}
406→        <div class='session-subtitle' style='font-size: 0.9em; color: #666; margin-top: 4px;'>{{
407→            message.session_subtitle }} ({{message.session_subtitle.session_id}})</div>
408→        {% endif %}
409→
410→    </div>
411→    {% else %}
412→    <div class='message {{ message.css_class }}'>
413→        <div class='header'>
414→            <span>{% if message.css_class == 'user' %}🤷 {% elif message.css_class == 'assistant' %}🤖 {% elif
415→                message.css_class == 'system' %}⚙️ {% endif %}{{ message.display_type }}</span>
416→            <div style='display: flex; flex-direction: column; align-items: flex-end; gap: 2px;'>
417→                <span class='timestamp'>{{ message.formatted_timestamp }}</span>
418→                {% if message.token_usage %}
419→                <span class='token-usage' style='font-size: 0.75em; color: #888;'>{{ message.token_usage }}</span>
420→                {% endif %}
421→            </div>
422→        </div>
423→        <div class='content'>{{ message.content_html | safe }}</div>
424→    </div>
425→    {% endif %}
426→    {% endfor %}
427→
428→    <a class="scroll-top" href="#title">🔝</a>
429→</body>
430→
431→</html>

