/* Collapsible details preview functionality */
.collapsible-details {
    position: relative;
}

.collapsible-details:not([open]) .details-content {
    display: block !important;
    max-height: 5em;
    overflow: hidden;
    position: relative;
    line-height: 1.4;
}

.collapsible-details:not([open]) .details-content::after {
    content: "";
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 1.5em;
    background: linear-gradient(transparent, var(--tool-bg, #f8f9fa66));
    pointer-events: none;
}

/* Set background color variables for different tool types */
.tool-result .collapsible-details:not([open]) .details-content::after {
    background: linear-gradient(transparent, #e8f5e866);
}

.tool-use .collapsible-details:not([open]) .details-content::after {
    background: linear-gradient(transparent, #e3f2fd66);
}

.thinking-content .collapsible-details:not([open]) .details-content::after {
    background: linear-gradient(transparent, #f0f0f066);
}

.collapsible-details:not([open]) .details-content pre {
    margin: 0;
    padding: 0;
    background: transparent;
}

.collapsible-details summary {
    position: relative;
}

.collapsible-details:not([open]) summary::after {
    content: " (click to expand)";
    font-size: 0.8em;
    color: #888;
    font-weight: normal;
}

